using Confectory.Core;
using System.Text.Json.Nodes;
namespace Confectory.Tests;
public sealed partial class PropertyBlueprintTests
{
    static JsonObject FieldRef(string id,JsonObject descriptor,string field,JsonObject target)
    {var node=Property(id,descriptor,field,target);node["kind"]="property-ref";node["intent"]="Alias actual field "+field;return node;}
    static JsonObject RefGraph(string feature)
    {var graph=Graph(feature);graph["profile"]=FeatureBlueprint.PropertyRefProfile;return graph;}
    string CreateValue(JsonObject descriptor,string field,string value)=>"calls.Create.Invoke("+Quote(descriptor.ToJsonString())+",new[]{"+Quote(Field(descriptor,field)["id"]!.ToString())+"},new object[]{"+value+"})";
    string ModelCall(string operation,JsonObject descriptor,string field,string target="target",string? value=null)=>"calls."+operation+".Invoke("+target+","+Quote(descriptor["id"]!.ToString())+","+Quote(Field(descriptor,field)["id"]!.ToString())+","+Quote(Field(descriptor,field)["hash"]!.ToString())+(value is null?"":","+value)+")";

    public void test_field_ref_repeated_acquisition_set_and_immediate_aliases_are_actual_same_storage()
    {
        var descriptor=Descriptor();const string feature="function Api::Value (object target) -> int {}";var graph=RefGraph(feature);graph["entry"]="first";
        graph["nodes"]=new JsonArray(FieldRef("first",descriptor,"health",Bind("input","target")),FieldRef("second",descriptor,"health",Bind("input","target")),Code("mutate",Sig("int",new Parameter("int","a","ref"),new Parameter("int","b","ref"),new Parameter("object","target")),new(){["a"]=Bind("node","first"),["b"]=Bind("node","second"),["target"]=Bind("input","target")},"Set","Read"));graph["edges"]=new JsonArray(Edge("first","second"),Edge("second","mutate"),Edge("mutate","exit:done"));graph["exits"]=new JsonObject{["done"]=Bind("node","mutate")};
        string field=Quote(Field(descriptor,"health")["id"]!.ToString()),hash=Quote(Field(descriptor,"health")["hash"]!.ToString());
        Write(graph,feature,descriptor,new(){["mutate"]="a=20;if(b!=20)throw new Exception(\"different field cells\");"+Alias("Set")+".Invoke(target,\"Api::Monster\","+field+","+hash+",30);if(a!=30||b!=30)throw new Exception(\"Set replaced an aliased cell\");b=40;return a;"});
        f.Body("App","main.csbody","object target="+CreateValue(descriptor,"health","10")+";object independent="+CreateValue(descriptor,"health","70")+";object before="+ModelCall("RefCell",descriptor,"health")+";Console.WriteLine(calls.Value.Invoke(target));Console.WriteLine("+ModelCall("Read",descriptor,"health")+");Console.WriteLine("+ModelCall("Read",descriptor,"health","independent")+");Console.WriteLine(ReferenceEquals(before,"+ModelCall("RefCell",descriptor,"health")+"));return 0;");Output(Build(),"40\n40\n70\nTrue");
        var assembled=Query(graph,feature,descriptor,"featureBlueprintAssemble",new(){["mutate"]=new JsonObject{["schema"]=1,["node"]="mutate",["definitionHash"]=Query(graph,feature,descriptor,"featureBlueprintNodes")["nodes"]!.AsArray().Single(n=>n!["id"]!.ToString()=="mutate")!["definitionHash"]!.DeepClone(),["source"]="a=9;return b;"}});Equal(FeatureBlueprint.PropertyRefGenerator,Text(assembled,"generator"));True(assembled["body"]!.ToString().Contains("ref ")&&assembled["body"]!.ToString().Contains("_field_cell.Value"));
    }
    public void test_field_ref_alias_local_set_updates_live_field_while_property_read_retains_snapshot()
    {
        var descriptor=Descriptor();const string feature="function Api::Value (object target) -> int {}";var graph=RefGraph(feature);graph["entry"]="read";graph["locals"]=new JsonArray(new JsonObject{["id"]="named",["name"]="Actual health",["type"]="int",["source"]=Bind("node","cell")});
        graph["nodes"]=new JsonArray(Property("read",descriptor,"health",Bind("input","target")),FieldRef("cell",descriptor,"health",Bind("input","target")),new JsonObject{["id"]="setLocal",["kind"]="set",["control"]="next",["intent"]="Assign through the field alias",["local"]="named",["signature"]=Sig("void",new Parameter("int","value")),["arguments"]=new JsonObject{["value"]=new JsonObject{["constant"]=20}}},Code("consume",Sig("int",new Parameter("int","snapshot"),new Parameter("int","a","ref"),new Parameter("int","b","ref")),new(){["snapshot"]=Bind("node","read"),["a"]=Bind("node","cell"),["b"]=Bind("local","named")}));graph["edges"]=new JsonArray(Edge("read","cell"),Edge("cell","setLocal"),Edge("setLocal","consume"),Edge("consume","exit:done"));graph["exits"]=new JsonObject{["done"]=Bind("node","consume")};Write(graph,feature,descriptor,new(){["consume"]="if(a!=20||b!=20)throw new Exception(\"alias local copied field\");b=30;return snapshot*100+a;"});
        f.Body("App","main.csbody","object target="+CreateValue(descriptor,"health","10")+";Console.WriteLine(calls.Value.Invoke(target));Console.WriteLine("+ModelCall("Read",descriptor,"health")+");return 0;");Output(Build(),"1030\n30");
    }
    public void test_field_ref_passes_actual_same_cell_through_private_ref_call_and_structural_set()
    {
        var descriptor=Descriptor();const string feature="function Api::Value (object target) -> int {}";var root=RefGraph(feature);root["entry"]="first";
        var child=new JsonObject{["schema"]=1,["profile"]=FeatureBlueprint.PropertyRefProfile,["entry"]="mutate",["nodes"]=new JsonArray(Code("mutate",Sig("int",new Parameter("int","a","ref"),new Parameter("int","b","ref")),new(){["a"]=Bind("input","a"),["b"]=Bind("input","b")})),["edges"]=new JsonArray(Edge("mutate","exit:done")),["exits"]=new JsonObject{["done"]=Bind("node","mutate")}};
        root["nodes"]=new JsonArray(FieldRef("first",descriptor,"health",Bind("input","target")),FieldRef("second",descriptor,"health",Bind("input","target")),PropertySet("set",descriptor,"health",Bind("input","target"),new(){["constant"]=50}),new JsonObject{["id"]="box",["kind"]="graph",["control"]="next",["intent"]="Actual ref call into private graph",["signature"]=Sig("int",new Parameter("int","a","ref"),new Parameter("int","b","ref")),["arguments"]=new JsonObject{["a"]=Bind("node","first"),["b"]=Bind("node","second")},["graph"]=child});root["edges"]=new JsonArray(Edge("first","second"),Edge("second","set"),Edge("set","box"),Edge("box","exit:done"));root["exits"]=new JsonObject{["done"]=Bind("node","box")};Write(root,feature,descriptor,new(){["box/mutate"]="if(a!=50||b!=50)throw new Exception(\"Set detached the field\");a=51;if(b!=51)throw new Exception(\"nested ref copied\");b=52;return a;"});
        f.Body("App","main.csbody","object target="+CreateValue(descriptor,"health","10")+";Console.WriteLine(calls.Value.Invoke(target));Console.WriteLine("+ModelCall("Read",descriptor,"health")+");return 0;");Output(Build(),"52\n52");
    }
    public void test_field_ref_exception_keeps_mutation_and_preexisting_alias_without_copy_out()
    {
        var descriptor=Descriptor();const string feature="function Api::Value (object target) -> void {}";var graph=RefGraph(feature);graph["entry"]="first";
        graph["nodes"]=new JsonArray(FieldRef("first",descriptor,"health",Bind("input","target")),FieldRef("second",descriptor,"health",Bind("input","target")),Code("fail",Sig("void",new Parameter("int","a","ref"),new Parameter("int","b","ref"),new Parameter("object","target")),new(){["a"]=Bind("node","first"),["b"]=Bind("node","second"),["target"]=Bind("input","target")},"Read"));graph["edges"]=new JsonArray(Edge("first","second"),Edge("second","fail"));string field=Quote(Field(descriptor,"health")["id"]!.ToString()),hash=Quote(Field(descriptor,"health")["hash"]!.ToString());Write(graph,feature,descriptor,new(){["fail"]="a=71;if(b!=71||(int)"+Alias("Read")+".Invoke(target,\"Api::Monster\","+field+","+hash+")!=71)throw new Exception(\"write was deferred\");b=72;throw new InvalidOperationException(\"after actual ref write\");"});
        f.Body("App","main.csbody","object target="+CreateValue(descriptor,"health","10")+";object cell="+ModelCall("RefCell",descriptor,"health")+";ref int held=ref ((System.Runtime.CompilerServices.StrongBox<int>)cell).Value;try{calls.Value.Invoke(target);throw new Exception(\"expected throw\");}catch(InvalidOperationException error)when(error.Message==\"after actual ref write\"){}Console.WriteLine(held);held=73;Console.WriteLine("+ModelCall("Read",descriptor,"health")+");Console.WriteLine(ReferenceEquals(cell,"+ModelCall("RefCell",descriptor,"health")+"));return 0;");Output(Build(),"72\n73\nTrue");
    }
    public void test_field_ref_bool_and_long_clr_cells_keep_full_existing_value_domain()
    {
        _=Descriptor();f.Add("Api","schema","Vitals","schema Api::Vitals {field enabled single general bool;field count single general long;}");f.Sync();var descriptor=RuntimeObjectContracts.Describe(f.Registry(),Owner);const string feature="function Api::Value (object target) -> long {}";var graph=RefGraph(feature);graph["entry"]="enabled";graph["nodes"]=new JsonArray(FieldRef("enabled",descriptor,"enabled",Bind("input","target")),FieldRef("count",descriptor,"count",Bind("input","target")),Code("mutate",Sig("long",new Parameter("bool","flag","ref"),new Parameter("long","count","ref")),new(){["flag"]=Bind("node","enabled"),["count"]=Bind("node","count")}));graph["edges"]=new JsonArray(Edge("enabled","count"),Edge("count","mutate"),Edge("mutate","exit:done"));graph["exits"]=new JsonObject{["done"]=Bind("node","mutate")};Write(graph,feature,descriptor,new(){["mutate"]="flag=!flag;count=long.MaxValue;return count;"});
        f.Body("App","main.csbody","object target=calls.Create.Invoke("+Quote(descriptor.ToJsonString())+",new[]{"+Quote(Field(descriptor,"enabled")["id"]!.ToString())+","+Quote(Field(descriptor,"count")["id"]!.ToString())+"},new object[]{false,1L});Console.WriteLine(calls.Value.Invoke(target));Console.WriteLine("+ModelCall("Read",descriptor,"enabled")+");return 0;");Output(Build(),long.MaxValue+"\nTrue");
