    public void test_field_ref_old_profiles_stale_contract_unsafe_fields_and_unavailable_sources_refuse()
    {
        _=Descriptor();f.Add("Api","function","Value","function Api::Value (object target) -> int {}");f.Add("Api","schema","Small","schema Api::Small {field n single general int;}");f.Add("Api","schema","Vitals","schema Api::Vitals {field health single general int;field f single general float;field d single general double;field text single general string;field samples multiple general int;field peer single reference Api::Vitals;field peers multiple reference Api::Vitals;field compound single compound Api::Small;field callback single function Api::Value;}");f.Sync();var descriptor=RuntimeObjectContracts.Describe(f.Registry(),Owner);const string feature="function Api::Value (object target) -> int {}";var graph=RefGraph(feature);graph["nodes"]=new JsonArray(FieldRef("read",descriptor,"health",Bind("input","target")));graph["edges"]=new JsonArray(Edge("read","exit:done"));graph["exits"]=new JsonObject{["done"]=Bind("node","read")};Equal("source-ready",Text(Query(graph,feature,descriptor),"state"));
        foreach(string profile in new[]{FeatureBlueprint.PropertyProfile,FeatureBlueprint.MethodsProfile,FeatureBlueprint.SwitchProfile,FeatureBlueprint.PropertySetProfile}){var old=graph.DeepClone().AsObject();old["profile"]=profile;Equal("GRAPH_NODE_KIND",Text(Query(old,feature,descriptor)["diagnostics"]![0]!,"code"));}
        foreach(string name in new[]{"f","d","text","samples","peer","peers","compound","callback"}){var bad=graph.DeepClone().AsObject();bad["nodes"]=new JsonArray(FieldRef("read",descriptor,name,Bind("input","target")));string code=Query(bad,feature,descriptor)["diagnostics"]![0]!["code"]!.ToString();True(code is "PROPERTY_REF_FIELD_UNSUPPORTED" or "PROPERTY_FIELD_UNSUPPORTED",code);}
        var stale=descriptor.DeepClone().AsObject();Field(stale,"health")["hash"]=new string('0',64);Equal("PROPERTY_FIELD_STALE",Text(Query(graph,feature,stale)["diagnostics"]![0]!,"code"));var before=graph.DeepClone().AsObject();before["entry"]="consume";before["nodes"]!.AsArray().Add(Code("consume",Sig("int",new Parameter("int","value","ref")),new(){["value"]=Bind("node","read")}));Equal("GRAPH_VALUE_UNAVAILABLE",Text(Query(before,feature,descriptor)["diagnostics"]![0]!,"code"));
    }
    public void test_field_ref_runtime_rejects_unsafe_unset_stale_and_legacy_without_weakening_checked_set()
    {
        _=Descriptor();const string feature="function Api::Value (object target) -> int {}";f.Add("Api","function","Value",feature);f.Add("Api","schema","Small","schema Api::Small {field n single general int;}");f.Add("Api","schema","Vitals","schema Api::Vitals {field health single general int;field f single general float;field d single general double;field text single general string;field samples multiple general int;field peer single reference Api::Vitals;field peers multiple reference Api::Vitals;field compound single compound Api::Small;field callback single function Api::Value;}");f.Add("Api","object","Foreign","object Api::Foreign {}");f.Sync();var descriptor=RuntimeObjectContracts.Describe(f.Registry(),Owner);var other=RuntimeObjectContracts.Describe(f.Registry(),"Api::Other");var foreign=RuntimeObjectContracts.Describe(f.Registry(),"Api::Foreign");var graph=RefGraph(feature);graph["nodes"]=new JsonArray(Property("read",descriptor,"health",Bind("input","target")));graph["edges"]=new JsonArray(Edge("read","exit:done"));graph["exits"]=new JsonObject{["done"]=Bind("node","read")};Write(graph,feature,descriptor,new());
        string field=Quote(Field(descriptor,"health")["id"]!.ToString()),hash=Quote(Field(descriptor,"health")["hash"]!.ToString());var checks=new List<string>{ModelCall("RefCell",descriptor,"health","null!"),ModelCall("RefCell",descriptor,"health","new object()"),ModelCall("RefCell",descriptor,"health","unset"),ModelCall("RefCell",descriptor,"health","other"),"calls.RefCell.Invoke(target,\"Api::Monster\","+field+","+Quote(new string('0',64))+")","calls.RefCell.Invoke(target,\"\","+field+","+hash+")","calls.RefCell.Invoke(target,\"Api::Monster\","+field+",\"\")"};
        foreach(string name in new[]{"f","d","text","samples","peer","peers","compound","callback"})checks.Add(ModelCall("RefCell",descriptor,name));
        checks.AddRange(new[]{ModelCall("Set",descriptor,"f",value:"float.NaN"),ModelCall("Set",descriptor,"d",value:"double.PositiveInfinity"),ModelCall("Set",descriptor,"text",value:"null!"),ModelCall("Set",descriptor,"samples",value:"null!"),ModelCall("Set",descriptor,"peer",value:"foreign"),ModelCall("Set",descriptor,"peers",value:"new object[]{foreign}")});
        string legacy="object legacy=new object[]{\"Confectory.ObjectModel.Instance/v1\",System.Text.Json.Nodes.JsonNode.Parse("+Quote(descriptor.ToJsonString())+")!,new System.Collections.Generic.Dictionary<string,object>{{"+field+",12}}};";
        f.Body("App","main.csbody","""
        void Refused(Action action){try{action();}catch(ArgumentException){Console.WriteLine("refused");return;}catch(InvalidOperationException){Console.WriteLine("refused");return;}catch(NotSupportedException){Console.WriteLine("refused");return;}throw new Exception("Unsafe field ref/value accepted");}
        """+"object target="+CreateValue(descriptor,"health","17")+";object unset=calls.Create.Invoke("+Quote(descriptor.ToJsonString())+",Array.Empty<string>(),Array.Empty<object>());object other=calls.Create.Invoke("+Quote(other.ToJsonString())+",Array.Empty<string>(),Array.Empty<object>());object foreign=calls.Create.Invoke("+Quote(foreign.ToJsonString())+",Array.Empty<string>(),Array.Empty<object>());var cell=(System.Runtime.CompilerServices.StrongBox<int>)"+ModelCall("RefCell",descriptor,"health")+";"+string.Join("",checks.Select(c=>"Refused(()=>"+c+");"))+"Console.WriteLine(cell.Value);"+ModelCall("Set",descriptor,"health",value:"19")+";Console.WriteLine(cell.Value);"+legacy+"Console.WriteLine("+ModelCall("Read",descriptor,"health","legacy")+");"+ModelCall("Set",descriptor,"health","legacy","22")+";Refused(()=>"+ModelCall("RefCell",descriptor,"health","legacy")+");Console.WriteLine("+ModelCall("Read",descriptor,"health","legacy")+");Console.WriteLine(((System.Collections.Generic.Dictionary<string,object>)((object[])legacy)[2])["+field+"] is int);"+ModelCall("Set",descriptor,"peer",value:"legacy")+";Console.WriteLine(ReferenceEquals("+ModelCall("Read",descriptor,"peer")+",legacy));return 0;");Output(Build(),string.Join("\n",Enumerable.Repeat("refused",checks.Count))+"\n17\n19\n12\nrefused\n22\nTrue\nTrue");
    }
